<script setup lang="ts">import * as echarts from 'echarts';import {onBeforeUnmount,onMounted,ref,watch} from 'vue';const props=defineProps<{option:any}>();const el=ref<HTMLElement>();let chart:any;const draw=()=>chart?.setOption(props.option,true);const resize=()=>chart?.resize();onMounted(()=>{chart=echarts.init(el.value!);draw();window.addEventListener('resize',resize)});watch(()=>props.option,draw,{deep:true});onBeforeUnmount(()=>{window.removeEventListener('resize',resize);chart?.dispose()})</script><template><div ref="el" class="h-80 w-full"></div></template>
